from math import gcd

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def count_divisible_by_either(x, n, m):
    cnt_n = x // n
    cnt_m = x // m
    cnt_d = x // lcm(n, m)

    return cnt_n + cnt_m - cnt_d * 2

def find_kth_smallest_divisible_by_one(n, m, k):
    l = 1
    r = 10**18

    while r - l > 1:
        mid = (l + r) // 2
        cnt = count_divisible_by_either(mid, n, m)
        if cnt >= k:
            r = mid
        else:
            l = mid

    return r

n, m, k = map(int, input().split())
print(find_kth_smallest_divisible_by_one(n, m, k))
